  }

  @Override
  public void matchConstraint(JSType constraint) {
    for (JSType alternate : alternates) {
      alternate.matchConstraint(constraint);
    }
  }

  @Override
  public boolean hasAnyTemplateInternal() {
    for (JSType alternate : alternates) {
      if (alternate.hasAnyTemplate()) {
        return true;
      }
    }
    return false;
  }
}

